import{_ as e,o as a,c as d,a5 as r}from"./chunks/framework.Bhkz_BpM.js";const p=JSON.parse('{"title":"Remaining 30% Roadmap","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","category":"电机控制","source":"motor","visibility":"public","title":"Remaining 30% Roadmap","tags":["motor-control"],"status":"learning","summary":"This roadmap starts after the 70% reviewed release is stable. It must not weaken the correctness gate: experimental algorithms and high-voltage power topics sta"},"headers":[],"relativePath":"content/motor/30-percent-roadmap.md","filePath":"content/motor/30-percent-roadmap.md","lastUpdated":1783096495000}'),o={name:"content/motor/30-percent-roadmap.md"};function n(i,t,s,l,c,m){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="remaining-30-roadmap" tabindex="-1">Remaining 30% Roadmap <a class="header-anchor" href="#remaining-30-roadmap" aria-label="Permalink to &quot;Remaining 30% Roadmap&quot;">​</a></h1><p>This roadmap starts after the 70% reviewed release is stable. It must not weaken the correctness gate: experimental algorithms and high-voltage power topics stay outside the recommended path until they have source evidence, simulation, bench/selftest records, hardware traces where applicable, and documented limits.</p><h2 id="front-end-algorithm-track" tabindex="-1">Front-End Algorithm Track <a class="header-anchor" href="#front-end-algorithm-track" aria-label="Permalink to &quot;Front-End Algorithm Track&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>Direction</th><th>Integration Rule</th><th>Acceptance Standard</th><th>Stage</th></tr></thead><tbody><tr><td>New sensorless observers</td><td>Add proof, offline simulation, and lxfoc <code>experimental</code> implementation before recommendation</td><td>Encoder comparison with angle error, valid speed range, and start success rate</td><td>R1</td></tr><tr><td>Flux observer refinement</td><td>Extend existing flux/SMO/PLL material and lxfoc observer interfaces</td><td>Full-speed error curve and low-speed boundary are documented</td><td>R1</td></tr><tr><td>HFI fusion</td><td>Combine HFI with flux/SMO/PLL by weighted handover</td><td>Low-speed HFI and medium/high-speed back-EMF observer switch without angle discontinuity</td><td>R2</td></tr><tr><td>MPC</td><td>Compare finite-control-set and continuous-control-set current MPC offline first</td><td>Offline bench, low-power hardware trace, CPU-time budget, and voltage limit record</td><td>R2</td></tr><tr><td>ADRC/LADRC</td><td>Keep as experimental until model, bandwidth, and saturation limits are explicit</td><td>Disturbance rejection report, output limit proof, and instability boundary notes</td><td>R2</td></tr><tr><td>LQR/LQI/LQG</td><td>Use as teaching and comparison controllers</td><td>Step and disturbance comparison against PI on the same plant</td><td>R3</td></tr></tbody></table></div><h2 id="advanced-power-track" tabindex="-1">Advanced Power Track <a class="header-anchor" href="#advanced-power-track" aria-label="Permalink to &quot;Advanced Power Track&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>Topic</th><th>Scope</th><th>Acceptance Standard</th><th>Stage</th></tr></thead><tbody><tr><td>Three-level hardware engineering</td><td>NPC/T-type gate drive, dead-time, neutral sampling, thermal split, and failure modes</td><td>Complete bring-up checklist and fault-mode table</td><td>R1</td></tr><tr><td>Three-level modulation extension</td><td>DPWM, overmodulation, and neutral-point balancing optimization</td><td>Results are comparable with PP-09 simulation outputs</td><td>R1</td></tr><tr><td>Vienna rectifier engineering</td><td>PLL, current sampling, PFC loops, neutral balance, and protection</td><td>PF, THD, bus ripple, and fault records from a safe bench</td><td>R2</td></tr><tr><td>LLC advanced design</td><td>Synchronous rectification, wide input range, burst mode, and magnetic loss</td><td>Reproducible design case with simulation and measured waveforms</td><td>R2</td></tr><tr><td>Bidirectional DC/DC</td><td>CLLC, DAB, phase-shift control, and storage interface</td><td>Bidirectional power-flow report and soft-switching boundary</td><td>R3</td></tr><tr><td>SiC/GaN</td><td>Gate drive, parasitics, dv/dt, EMI, protection, and PCB layout</td><td>Device-selection and layout-review checklist</td><td>R3</td></tr></tbody></table></div><h2 id="community-and-maintenance" tabindex="-1">Community And Maintenance <a class="header-anchor" href="#community-and-maintenance" aria-label="Permalink to &quot;Community And Maintenance&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>Task</th><th>Acceptance Standard</th><th>Stage</th></tr></thead><tbody><tr><td>Dataset catalog</td><td>Public traces are archived with calibration, manifest, report, and comparison files</td><td>R1</td></tr><tr><td>Hardware adapters</td><td>Minimum sampling, serial/CAN, and safety requirements are documented per platform</td><td>R1</td></tr><tr><td>Versioned protocols</td><td><code>lxfoc_config</code> and trace schemas use semantic versions with migration notes</td><td>R1</td></tr><tr><td>Issue labels</td><td><code>good-first-proof</code>, <code>needs-simulation</code>, <code>needs-hardware-test</code>, and <code>experimental-algorithm</code> are documented</td><td>R2</td></tr><tr><td>Release reports</td><td>Each release lists newly reviewed/verified modules, hardware platforms, and known wrong or incomplete content</td><td>R2</td></tr><tr><td>Community review</td><td>Every community proof PR receives formula, simulation, and experiment checklist review</td><td>R3</td></tr></tbody></table></div><h2 id="promotion-rule" tabindex="-1">Promotion Rule <a class="header-anchor" href="#promotion-rule" aria-label="Permalink to &quot;Promotion Rule&quot;">​</a></h2><p>No R1/R2/R3 item may move from <code>experimental</code> or <code>reviewed</code> to <code>verified</code> unless:</p><ol><li>The proof file passes schema and semantic checks.</li><li>The source references are explicit and traceable.</li><li>Simulation artifacts are reproducible.</li><li>lxfoc code, when present, has bench or selftest coverage.</li><li>Hardware-dependent claims include calibrated raw traces and generated reports.</li><li>The known-limitations section states the safe operating boundary.</li></ol>',11)])])}const u=e(o,[["render",n]]);export{p as __pageData,u as default};
